// LAB: Grow a collection under a hard limit
// Append an element only when a vector is below a fixed maximum size. Rejection must leave the vector unchanged. Do not retain an element pointer while growing it.
// This starter verifies the original example. Extend it to satisfy the lab checks.
#include <cassert>
#include <iostream>
#include <numeric>
#include <vector>

int main() {
    std::vector<int> values;
    values.reserve(1);
    values.push_back(4);
    values.push_back(6);
    values.push_back(8);
    const int total = std::accumulate(values.begin(), values.end(), 0);
    std::cout << values.size() << ' ' << total << '\n';
    assert(values.size() == 3 && total == 18);
}

#include <cassert>
#include <cstddef>
#include <iostream>
#include <vector>

bool append_bounded(std::vector<int>& values, int value, std::size_t maximum) {
    if(values.size() >= maximum) return false;
    values.push_back(value);
    return true;
}

int main() {
    std::vector<int> values{4,6};
    assert(append_bounded(values,8,3));
    const auto before = values;
    assert(!append_bounded(values,10,3) && values == before);
    std::vector<int> empty;
    assert(!append_bounded(empty,1,0));
    std::cout << "size=" << values.size() << " last=" << values.back() << " limit=preserved\n";
}
